import{_ as t,C as r,o as d,c as l,a4 as a,E as c}from"./chunks/framework.DAD9IEko.js";const P=JSON.parse('{"title":"PP-11 Boost PFC 与母线动态","description":"","frontmatter":{"date":"2026-06-11T00:00:00.000Z","section":"电机控制","chapter":"power-path","chapterTitle":"功率链路","chapterOrder":40,"category":"功率链路","source":"motor","visibility":"public","title":"PP-11 Boost PFC 与母线动态","tags":["motor-control"],"status":"learning","summary":"> **状态**: reviewed > **定位**: 本模块解释 PFC 母线不是理想电压源，母线动态会直接改变 FOC 电压裕量、弱磁边界和保护行为。","navGroup":"基础与硬件","navGroupOrder":20},"headers":[],"relativePath":"content/motor/power-path/PP-11-Boost-PFC-Bus-Dynamics.md","filePath":"content/motor/power-path/PP-11-Boost-PFC-Bus-Dynamics.md","lastUpdated":1783181958000}'),i={name:"content/motor/power-path/PP-11-Boost-PFC-Bus-Dynamics.md"};function s(n,o,h,p,u,b){const e=r("MermaidDiagram");return d(),l("div",null,[o[0]||(o[0]=a('<h1 id="pp-11-boost-pfc-与母线动态" tabindex="-1">PP-11 Boost PFC 与母线动态 <a class="header-anchor" href="#pp-11-boost-pfc-与母线动态" aria-label="Permalink to &quot;PP-11 Boost PFC 与母线动态&quot;">​</a></h1><blockquote><p><strong>状态</strong>: reviewed<br><strong>定位</strong>: 本模块解释 PFC 母线不是理想电压源，母线动态会直接改变 FOC 电压裕量、弱磁边界和保护行为。</p></blockquote><p><strong>模块编号：</strong> PP-11<br><strong>模块名称：</strong> Boost PFC 与母线动态<br><strong>文档版本：</strong> v1.1<br><strong>前置知识：</strong> PP-01 DC-DC 基础拓扑、PP-04 PFC 功率因数校正、ALG-03 PI 电流调节器<br><strong>难度等级：</strong></p><hr><h2 id="_1-核心摘要" tabindex="-1">1. 核心摘要 <a class="header-anchor" href="#_1-核心摘要" aria-label="Permalink to &quot;1.  核心摘要&quot;">​</a></h2><p><strong>一句话：</strong> Boost PFC 的母线不是理想电压源，而是由输入电压、电流内环、电压外环、母线电容和负载功率共同决定的动态节点；它的跌落、纹波和保护阈值会直接改变 FOC 的电压限幅、弱磁边界和故障行为。</p><p><strong>认知挂钩：</strong> 很多电机控制调试把 <code>Vdc</code> 当常数，但真实母线更像一个带弹性的水箱。PFC 往水箱补能，逆变器从水箱取能，母线电容只是缓冲。电机突然加速时取能增加，如果 PFC 来不及补，水位就会下跌，FOC 可用电压马上变小。</p><p><strong>核心问题链：</strong></p>',8)),c(e,{code:"flowchart%20TD%0A%20%20A%5B%22%E8%BE%93%E5%85%A5%E7%94%B5%E5%8E%8B%E5%8F%98%E5%8C%96%E6%88%96%E8%B4%9F%E8%BD%BD%E9%98%B6%E8%B7%83%22%5D%20--%3E%20B%5B%22PFC%20%E7%94%B5%E6%B5%81%E5%86%85%E7%8E%AF%E8%B0%83%E8%8A%82%E8%BE%93%E5%85%A5%E7%94%B5%E6%B5%81%22%5D%0A%20%20B%20--%3E%20C%5B%22%E7%94%B5%E5%8E%8B%E5%A4%96%E7%8E%AF%E6%81%A2%E5%A4%8D%20Vdc%22%5D%0A%20%20C%20--%3E%20D%5B%22%E6%AF%8D%E7%BA%BF%E7%94%B5%E5%AE%B9%E6%89%BF%E6%8B%85%E6%9A%82%E6%80%81%E8%83%BD%E9%87%8F%E5%B7%AE%22%5D%0A%20%20D%20--%3E%20E%5B%22vbus_V%20%E6%94%B9%E5%8F%98%20FOC%20%E7%94%B5%E5%8E%8B%E9%99%90%E5%B9%85%22%5D%0A%20%20E%20--%3E%20F%5B%22%E5%BD%B1%E5%93%8D%E7%94%B5%E6%B5%81%E8%B7%9F%E8%B8%AA%E3%80%81%E5%BC%B1%E7%A3%81%E5%92%8C%E4%BF%9D%E6%8A%A4%22%5D%0A"}),o[1]||(o[1]=a(`<hr><h2 id="_2-问题引入" tabindex="-1">2. 问题引入 <a class="header-anchor" href="#_2-问题引入" aria-label="Permalink to &quot;2.  问题引入&quot;">​</a></h2><h3 id="工程师的真实困惑" tabindex="-1">工程师的真实困惑 <a class="header-anchor" href="#工程师的真实困惑" aria-label="Permalink to &quot;工程师的真实困惑&quot;">​</a></h3><blockquote><p><strong>场景 1：电流环突然失真，但 PI 参数没变</strong><br> 电机加速时 <code>iq_ref</code> 阶跃，电流环一开始跟踪正常，随后 <code>uq</code> 顶到限幅，<code>iq</code> 误差增大。检查后发现不是 PI 参数问题，而是母线从 380 V 跌到 320 V，电压裕量不够。</p></blockquote><blockquote><p><strong>场景 2：弱磁动作点和理论不一致</strong><br> 按额定母线计算，电机应在某转速后进入弱磁。但实际运行中，母线纹波和负载阶跃让 <code>vbus</code> 低于额定值，弱磁提前动作。</p></blockquote><blockquote><p><strong>场景 3：欠压保护反复触发</strong><br> PFC 还在恢复母线，逆变器侧已经触发欠压停机。阈值没有迟滞或恢复条件过严，导致系统在启动和负载阶跃时反复进出故障。</p></blockquote><h3 id="核心问题" tabindex="-1">核心问题 <a class="header-anchor" href="#核心问题" aria-label="Permalink to &quot;核心问题&quot;">​</a></h3><p>为什么学习 Boost PFC 不能只看功率因数和输出电压稳态值？</p><p><strong>答案：</strong> 因为电机驱动关注的是动态可用电压。Boost PFC 的外环带宽、母线电容能量、输入跌落和负载阶跃都会反映到 <code>vbus_V</code>，进而影响 FOC 电压限幅和保护。</p><h3 id="学习目标" tabindex="-1">学习目标 <a class="header-anchor" href="#学习目标" aria-label="Permalink to &quot;学习目标&quot;">​</a></h3><p>读完本模块，你将能够：</p><p>说明 Boost PFC 电流内环、电压外环和母线电容的分工<br> 解释负载阶跃为什么会造成母线跌落<br> 判断母线动态如何影响 dq 电压限幅和弱磁边界<br> 设计包含 <code>vbus_V</code> 的 lxfoc trace 数据要求<br> 制定 PFC-逆变器联调中的欠压/过压验证任务</p><hr><h2 id="_3-直观理解" tabindex="-1">3. 直观理解 <a class="header-anchor" href="#_3-直观理解" aria-label="Permalink to &quot;3.  直观理解&quot;">​</a></h2><h3 id="_3-1-boost-pfc-的基本闭环" tabindex="-1">3.1 Boost PFC 的基本闭环 <a class="header-anchor" href="#_3-1-boost-pfc-的基本闭环" aria-label="Permalink to &quot;3.1 Boost PFC 的基本闭环&quot;">​</a></h3><p>典型单相或三相 Boost PFC 包含：</p><ul><li>电流内环：让输入电流跟踪整流电压形状。</li><li>电压外环：维持直流母线平均值。</li><li>输入电压前馈：降低输入电压变化对电流环的扰动。</li><li>母线电容：承担两倍工频功率脉动和负载阶跃能量。</li></ul><h3 id="_3-2-母线电容的能量缓冲" tabindex="-1">3.2 母线电容的能量缓冲 <a class="header-anchor" href="#_3-2-母线电容的能量缓冲" aria-label="Permalink to &quot;3.2 母线电容的能量缓冲&quot;">​</a></h3><p>母线电容储能为：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>E = 1/2 * Cbus * Vdc^2</span></span></code></pre></div><p>当负载功率瞬间大于 PFC 输入功率时，能量差由母线电容提供，<code>Vdc</code> 下降。电容越大，同样能量缺口造成的电压跌落越小；但电容越大，体积、成本、预充电和浪涌管理越困难。</p><h3 id="_3-3-foc-看到的是实时母线" tabindex="-1">3.3 FOC 看到的是实时母线 <a class="header-anchor" href="#_3-3-foc-看到的是实时母线" aria-label="Permalink to &quot;3.3 FOC 看到的是实时母线&quot;">​</a></h3><p>FOC 的调制电压不是由额定母线决定，而是由实时 <code>vbus</code> 决定。即使算法参数不变，<code>vbus</code> 下降也会让同一个 <code>ud/uq</code> 指令更接近限幅。</p><hr><h2 id="_4-技术原理" tabindex="-1">4. 技术原理 <a class="header-anchor" href="#_4-技术原理" aria-label="Permalink to &quot;4.  技术原理&quot;">​</a></h2><h3 id="_4-1-母线对-lxfoc-的影响" tabindex="-1">4.1 母线对 lxfoc 的影响 <a class="header-anchor" href="#_4-1-母线对-lxfoc-的影响" aria-label="Permalink to &quot;4.1 母线对 lxfoc 的影响&quot;">​</a></h3><p>lxfoc 中与母线相关的关键点：</p><div class="kb-table-scroll"><table><thead><tr><th>lxfoc 模块</th><th>受影响行为</th></tr></thead><tbody><tr><td><code>control_current</code></td><td><code>vbus / sqrt(3)</code> 决定 dq 电压限幅</td></tr><tr><td><code>transform_svpwm</code></td><td>duty 计算和过调制边界依赖母线</td></tr><tr><td><code>field_weakening</code></td><td>弱磁提前或滞后取决于可用电压</td></tr><tr><td><code>protect</code></td><td>欠压/过压迟滞决定是否停机</td></tr><tr><td><code>motor_config</code></td><td><code>vbus</code> 应作为运行时参数同步</td></tr></tbody></table></div><h3 id="_4-2-电压外环与负载阶跃" tabindex="-1">4.2 电压外环与负载阶跃 <a class="header-anchor" href="#_4-2-电压外环与负载阶跃" aria-label="Permalink to &quot;4.2 电压外环与负载阶跃&quot;">​</a></h3><p>Boost PFC 电压外环通过调节输入电流幅值恢复母线。负载阶跃发生时：</p><ol><li>逆变器从母线取走更多功率。</li><li>母线电容先承担能量缺口，<code>Vdc</code> 下跌。</li><li>电压外环检测到误差，增加输入电流幅值。</li><li>电流内环提高输入功率，母线恢复。</li></ol><p>恢复过程的速度取决于外环带宽、输入电压、限流策略和电容容量。</p><h3 id="_4-3-欠压-过压保护" tabindex="-1">4.3 欠压/过压保护 <a class="header-anchor" href="#_4-3-欠压-过压保护" aria-label="Permalink to &quot;4.3 欠压/过压保护&quot;">​</a></h3><p>保护阈值必须带迟滞和时间条件：</p><ul><li>欠压触发阈值防止低母线下强行输出导致过调制或电流失控。</li><li>欠压恢复阈值应高于触发阈值，避免反复抖动。</li><li>过压保护要考虑制动能量、PFC 控制饱和和母线电容耐压。</li><li>故障记录必须包含 <code>vbus_V</code> 和 <code>fault_flags</code>。</li></ul><h3 id="_4-4-trace-数据要求" tabindex="-1">4.4 Trace 数据要求 <a class="header-anchor" href="#_4-4-trace-数据要求" aria-label="Permalink to &quot;4.4 Trace 数据要求&quot;">​</a></h3><p>实物 trace 必须至少包含：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>time_s, id_A, iq_A, id_ref_A, iq_ref_A, ud_V, uq_V,</span></span>
<span class="line"><span>duty_a, duty_b, duty_c, vbus_V, fault_flags</span></span></code></pre></div><p>如果缺少 <code>vbus_V</code>，该实验不得用于验证母线动态，只能作为普通电流环实验。</p><hr><h2 id="_5-交叉视角" tabindex="-1">5. 交叉视角 <a class="header-anchor" href="#_5-交叉视角" aria-label="Permalink to &quot;5.  交叉视角&quot;">​</a></h2><h3 id="_5-1-与-pi-电流环的关系" tabindex="-1">5.1 与 PI 电流环的关系 <a class="header-anchor" href="#_5-1-与-pi-电流环的关系" aria-label="Permalink to &quot;5.1 与 PI 电流环的关系&quot;">​</a></h3><p>电流环输出的是电压指令。PI 参数再合理，如果母线不足，控制器也无法生成足够电压。母线动态问题常被误判为 PI 参数过小、前馈不足或电机参数错误。</p><h3 id="_5-2-与弱磁的关系" tabindex="-1">5.2 与弱磁的关系 <a class="header-anchor" href="#_5-2-与弱磁的关系" aria-label="Permalink to &quot;5.2 与弱磁的关系&quot;">​</a></h3><p>弱磁控制的本质是用负 <code>id</code> 换取高速区电压裕量。当 <code>vbus</code> 下跌时，可用电压降低，弱磁应提前介入；当 <code>vbus</code> 恢复时，弱磁可以退出或减弱。弱磁边界必须使用实时母线，而不是固定额定值。</p><h3 id="_5-3-与系统验证的关系" tabindex="-1">5.3 与系统验证的关系 <a class="header-anchor" href="#_5-3-与系统验证的关系" aria-label="Permalink to &quot;5.3 与系统验证的关系&quot;">​</a></h3><p>PFC 和 FOC 不能只各自验证稳态。整机必须验证输入跌落、负载阶跃、再生制动和故障恢复等跨域场景，否则知识库中“电源章节”和“算法章节”无法闭环。</p><hr><h2 id="_6-工程案例" tabindex="-1">6. 工程案例 <a class="header-anchor" href="#_6-工程案例" aria-label="Permalink to &quot;6.  工程案例&quot;">​</a></h2><h3 id="案例-负载阶跃导致-foc-电压限幅" tabindex="-1">案例：负载阶跃导致 FOC 电压限幅 <a class="header-anchor" href="#案例-负载阶跃导致-foc-电压限幅" aria-label="Permalink to &quot;案例：负载阶跃导致 FOC 电压限幅&quot;">​</a></h3><p><strong>条件：</strong></p><ul><li>Boost PFC 目标母线：380 V</li><li>PMSM 在中高速运行</li><li><code>iq_ref</code> 从 2 A 阶跃到 8 A</li><li>母线在 30 ms 内跌落到 330 V 后恢复</li></ul><p><strong>观察量：</strong></p><div class="kb-table-scroll"><table><thead><tr><th>场景</th><th>观察量</th><th>通过标准</th></tr></thead><tbody><tr><td>负载阶跃</td><td><code>Vdc, id, iq, duty</code></td><td>电流环不发生 duty 溢出</td></tr><tr><td>输入跌落</td><td><code>Vdc, fault_flags</code></td><td>欠压保护阈值和迟滞符合配置</td></tr><tr><td>弱磁边界</td><td><code>uq, ud, speed</code></td><td>弱磁动作后电压矢量不超过限幅</td></tr></tbody></table></div><p><strong>分析步骤：</strong></p><ol><li>对齐 <code>iq_ref</code> 阶跃时间和 <code>vbus_V</code> 跌落时间。</li><li>检查 <code>sqrt(ud_V^2 + uq_V^2)</code> 是否接近实时电压限幅。</li><li>检查 <code>duty_a/b/c</code> 是否接近 0 或 1。</li><li>检查 <code>fault_flags</code> 是否出现欠压或过调制。</li><li>如果限幅先于电流误差出现，优先分析母线动态，而不是先改 PI 参数。</li></ol><hr><h2 id="_7-实践练习" tabindex="-1">7. 实践练习 <a class="header-anchor" href="#_7-实践练习" aria-label="Permalink to &quot;7.  实践练习&quot;">​</a></h2><h3 id="练习-1-能量判断" tabindex="-1">练习 1：能量判断 <a class="header-anchor" href="#练习-1-能量判断" aria-label="Permalink to &quot;练习 1：能量判断&quot;">​</a></h3><p>为什么负载阶跃时母线会先跌落，再恢复？</p><p><strong>参考答案：</strong></p><p>负载功率瞬间增加时，PFC 输入功率不能立即跟上，能量缺口先由母线电容提供，因此 <code>Vdc</code> 下跌。电压外环随后提高输入电流幅值，输入功率增加后母线恢复。</p><h3 id="练习-2-trace-必要性" tabindex="-1">练习 2：Trace 必要性 <a class="header-anchor" href="#练习-2-trace-必要性" aria-label="Permalink to &quot;练习 2：Trace 必要性&quot;">​</a></h3><p>某次电流环实验没有记录 <code>vbus_V</code>，能否用于验证母线动态？</p><p><strong>参考答案：</strong></p><p>不能。没有 <code>vbus_V</code> 就无法判断电压限幅、弱磁动作和欠压保护是否由母线变化触发，只能作为普通电流环实验。</p><h3 id="练习-3-保护迟滞" tabindex="-1">练习 3：保护迟滞 <a class="header-anchor" href="#练习-3-保护迟滞" aria-label="Permalink to &quot;练习 3：保护迟滞&quot;">​</a></h3><p>欠压保护为什么需要恢复阈值高于触发阈值？</p><p><strong>参考答案：</strong></p><p>如果触发和恢复阈值相同，母线在阈值附近纹波或缓慢恢复时会反复进出故障。迟滞可以避免保护抖动。</p><h3 id="练习-4-误判排查" tabindex="-1">练习 4：误判排查 <a class="header-anchor" href="#练习-4-误判排查" aria-label="Permalink to &quot;练习 4：误判排查&quot;">​</a></h3><p>电机高速加速时 <code>iq</code> 跟踪误差增大。为什么不能第一步就调大 PI 增益？</p><p><strong>参考答案：</strong></p><p>高速加速时可能已经受母线电压限幅约束。若 <code>ud/uq</code> 接近实时限幅，调大 PI 只会更快饱和，不能增加物理可用电压。应先检查 <code>vbus_V</code>、duty 和限幅状态。</p><hr><h2 id="_8-正确性证据" tabindex="-1">8. 正确性证据 <a class="header-anchor" href="#_8-正确性证据" aria-label="Permalink to &quot;8.  正确性证据&quot;">​</a></h2><p>主要对标：</p><ul><li>Erickson and Maksimovic, <em>Fundamentals of Power Electronics</em>, averaged switch modeling and control.</li><li>Mohan, <em>Power Electronics</em>, PFC rectifier chapters.</li><li>lxfoc <code>lxfoc_motor_config_update()</code> 与电压限幅实现。</li></ul><p>本模块的 proof 文件位于 <code>_proofs/power-path/PP-11-Boost-PFC-Bus-Dynamics.module-proof.yaml</code>。</p>`,79))])}const q=t(i,[["render",s]]);export{P as __pageData,q as default};
